      out.write("                    opacity: 0;\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("        `;\r\n");
      out.write("        document.head.appendChild(style);\r\n");
      out.write("\r\n");
      out.write("        // Form validation and enhancement\r\n");
