      out.write("            });\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        function createSparkle(x, y) {\r\n");
      out.write("            const sparkle = document.createElement('div');\r\n");
      out.write("            sparkle.innerHTML = '✨';\r\n");
      out.write("            sparkle.style.cssText = `\r\n");
      out.write("                position: fixed;\r\n");
