      out.write("\r\n");
      out.write("        // Add sparkle animation\r\n");
      out.write("        const sparkleStyleSheet = document.createElement('style');\r\n");
      out.write("        sparkleStyleSheet.textContent = `\r\n");
      out.write("            @keyframes sparkleAnim {\r\n");
